cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void max_reduction_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t reduce_dim_size,
    int64_t outer_size,
    int64_t inner_size
) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= outer_size * inner_size) return;

    int64_t outer_idx = idx / inner_size;
    int64_t inner_idx = idx % inner_size;

    // Initialize maximum value
    half max_val = input[outer_idx * reduce_dim_size * inner_size + inner_idx];

    // Perform reduction along the specified dimension
    for (int64_t i = 1; i < reduce_dim_size; ++i) {
        half val = input[(outer_idx * reduce_dim_size + i) * inner_size + inner_idx];
        max_val = __hgt__(val, max_val) ? val : max_val;
    }

    output[idx] = max_val;
}

// Host wrapper function
extern "C" void launch_max_reduction(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t reduce_dim_size,
    int64_t outer_size,
    int64_t inner_size
) {
    const int block_size = 256;
    const int grid_size = (outer_size * inner_size + block_size - 1) / block_size;

    max_reduction_kernel<<<grid_size, block_size>>>(
        input, output, total_elements, reduce_dim_size, outer_size, inner_size
    );

    cudaDeviceSynchronize();
}
"""

# Python wrapper
def launch_max_reduction(input_tensor, dim):
    """
    Launches CUDA kernel for max reduction along specified dimension.

    Args:
        input_tensor: Input tensor of shape [batch, dim1, dim2]
        dim: Dimension to reduce over

    Returns:
        Output tensor after max reduction
    """
    # Ensure input is contiguous and fp16
    input_tensor = input_tensor.contiguous().to(torch.float16)

    # Get input shape
    shape = input_tensor.shape
    total_elements = shape.numel()

    # Calculate dimensions for reduction
    reduce_dim_size = shape[dim]
    outer_size = 1
    inner_size = 1

    for i in range(dim):
        outer_size *= shape[i]
    for i in range(dim + 1, len(shape)):
        inner_size *= shape[i]

    # Allocate output tensor
    output_shape = list(shape)
    output_shape.pop(dim)
    output = torch.empty(output_shape, dtype=torch.float16, device=input_tensor.device)

    # Launch kernel
    load_inline(
        name="max_reduction_ext",
        cpp_sources=cuda_source,
        functions=["launch_max_reduction"],
        verbose=False
    )

    # Call the kernel
    from max_reduction_ext import launch_max_reduction as launch_kernel

    launch_kernel(
        input_tensor.data_ptr(),
        output.data_ptr(),
        total_elements,
        reduce_dim_size,
        outer_size,
        inner_size
    )

    return output

